Task ID: java_pagination_boundary
Scenario: Pagination code has an index boundary bug and unstable empty-page behavior.

Instructions:
Find the concrete correctness bug in this pagination flow and propose the smallest patch. Be explicit about what happens on the last page and on out-of-range requests.

Project snapshot:

=== File: src/main/java/com/example/user/UserQueryService.java ===
package com.example.user;

import java.util.List;

public class UserQueryService {
    private final UserRepository userRepository;

    public UserQueryService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public List<User> list(int page, int size) {
        int offset = page * size;
        return userRepository.findRange(offset, offset + size);
    }
}

=== File: src/main/java/com/example/user/UserRepository.java ===
package com.example.user;

import java.util.List;

public interface UserRepository {
    List<User> findRange(int startInclusive, int endInclusive);
}

=== File: src/main/java/com/example/user/InMemoryUserRepository.java ===
package com.example.user;

import java.util.ArrayList;
import java.util.List;

public class InMemoryUserRepository implements UserRepository {
    private final List<User> users = new ArrayList<>();

    @Override
    public List<User> findRange(int startInclusive, int endInclusive) {
        return users.subList(startInclusive, endInclusive);
    }
}
